package dev.simplified.shared.javac;

import com.sun.tools.javac.tree.JCTree.JCAnnotation;
import com.sun.tools.javac.tree.JCTree.JCClassDecl;
import com.sun.tools.javac.tree.JCTree.JCMethodDecl;
import com.sun.tools.javac.tree.JCTree.JCModifiers;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.util.List;

import java.util.Collections;
import java.util.WeakHashMap;

/**
 * Tags JCTree nodes as "generated by {@code @ClassBuilder}" so:
 * <ul>
 *   <li>collision detection skips injection when a user already wrote a
 *       member with the same name/shape,</li>
 *   <li>downstream tooling or future processors can recognise our output
 *       without inspecting modifiers or annotations,</li>
 *   <li>the IDE-side {@code LineMarkerProvider} can mirror the "generated"
 *       attribution when it synthesises the same members,</li>
 *   <li>{@link GeneratedAnnotations} can attach {@code @Generated} at the same
 *       moment, keeping the in-process mark and the class-file marker in step.</li>
 * </ul>
 *
 * <p>javac's {@link JCTree} has no user-data slot, so marks live in a
 * process-local weak-identity set. Lifetime is bounded to the annotation-
 * processing round since the processor re-runs per compilation.
 */
public final class AstMarkers {

    private static final java.util.Set<JCTree> GENERATED =
        Collections.newSetFromMap(new WeakHashMap<>());

    /** Per-pass idempotency marks, keyed by the pass's own name. */
    private static final java.util.Map<String, java.util.Set<JCTree>> PASSES =
        new java.util.HashMap<>();

    /** Generated node to the authored declaration its documentation describes. */
    private static final java.util.Map<JCTree, JCTree> DOC_SOURCES =
        java.util.Collections.synchronizedMap(new WeakHashMap<>());

    private AstMarkers() {
    }

    /**
     * Marks the given node as generated without attaching {@code @Generated}.
     * For nodes that carry no modifiers and so cannot hold an annotation - a
     * static initialiser block being the one such node the pipeline emits.
     * Prefer {@link #markGenerated(JCTree, GeneratedAnnotations)} everywhere
     * else, so the in-process mark and the marker in the class file cannot
     * drift apart.
     */
    public static void markGenerated(JCTree node) {
        if (node != null) GENERATED.add(node);
    }

    /**
     * Marks the given node as generated and attaches {@code @Generated} to it.
     *
     * <p>Attaching here rather than at each {@code make.Modifiers(..)} call
     * makes the invariant structural: a node the pipeline marks is a node whose
     * class file carries the marker, and coverage tools filter exactly what
     * this project synthesised. Nodes with no modifiers list are marked and
     * left otherwise untouched, and {@code generated} being disabled reduces
     * this to the plain mark.
     *
     * @param node the freshly built node
     * @param generated the marker factory, gated by {@code emitGenerated}
     */
    public static void markGenerated(JCTree node, GeneratedAnnotations generated) {
        if (node == null) return;
        GENERATED.add(node);
        if (generated == null) return;
        JCModifiers mods = modifiersOf(node);
        if (mods == null) return;
        List<JCAnnotation> marker = generated.generated();
        if (marker.isEmpty()) return;
        mods.annotations = mods.annotations.appendList(marker);
    }

    /** The node's modifiers, or {@code null} for a node kind that has none. */
    private static JCModifiers modifiersOf(JCTree node) {
        if (node instanceof JCMethodDecl m) return m.mods;
        if (node instanceof JCClassDecl c) return c.mods;
        if (node instanceof JCVariableDecl v) return v.mods;
        return null;
    }

    /** Returns {@code true} when the node was produced by the mutation pipeline. */
    public static boolean isGenerated(JCTree node) {
        return GENERATED.contains(node);
    }

    /**
     * Records that the named pass has already rewritten the node.
     *
     * <p>Separate from {@link #isGenerated(JCTree)} because the two questions
     * are different ones. "Generated" is about authorship and drives collision
     * detection; this is one pass's own idempotency, so that whichever dispatch
     * path reaches a node first wins and any later one is a no-op. Sharing the
     * generated set for it makes two passes over the same node mutually
     * exclusive: a body rewrite that marks the blocks it walked would silence
     * every other pass that reads the same flag, and the symptom is an
     * annotation that quietly does nothing.
     *
     * @param node the node the pass has finished with
     * @param pass the pass's own key
     */
    public static void markPass(JCTree node, String pass) {
        if (node != null) passMarks(pass).add(node);
    }

    /**
     * Whether the named pass has already rewritten the node.
     *
     * @param node the node about to be rewritten
     * @param pass the pass's own key
     * @return {@code true} when the pass has already claimed this node
     */
    public static boolean isPassMarked(JCTree node, String pass) {
        return node != null && passMarks(pass).contains(node);
    }

    private static java.util.Set<JCTree> passMarks(String pass) {
        synchronized (PASSES) {
            return PASSES.computeIfAbsent(pass,
                key -> Collections.newSetFromMap(new WeakHashMap<>()));
        }
    }

    /**
     * Records the authored declaration whose documentation describes a generated
     * node.
     *
     * <p>A generated accessor's prose is the field's prose, and only the pass
     * that mints the accessor holds both nodes at once. Recording the pairing
     * here is what lets a later reader carry the field's javadoc onto the member
     * without matching names back to fields - a match that would be a second,
     * drifting copy of the naming rules the pass already applied.
     *
     * @param node the freshly built node
     * @param source the authored declaration the node derives from
     */
    public static void markDocSource(JCTree node, JCTree source) {
        if (node != null && source != null) DOC_SOURCES.put(node, source);
    }

    /**
     * The authored declaration whose documentation describes the given node.
     *
     * @param node the generated node
     * @return the declaration it derives from, or {@code null} when the node
     *         derives from no single one
     */
    public static JCTree docSourceOf(JCTree node) {
        return node == null ? null : DOC_SOURCES.get(node);
    }

}
